  JSONObject inputs=copy(fixture.getJSONObject("inputs"));String filename="ww-store-check-"+token+"-main.sqlite";File mainFile=new File(context.getFilesDir(),filename);owned.add(mainFile);check(!mainFile.exists(),"fresh own path");WatchlistWorkspaceStore store=new WatchlistWorkspaceStore(context,filename);check(scalar(mainFile,"PRAGMA application_id")==1465340725,"actual rawQuery appId consumed/read-back");check(store.read(inputs).getString("state").equals("uninitialized")&&scalar(mainFile,"SELECT count(*) FROM watchlist_workspace")==0,"read no projection/write");rejects(()->store.save(new JSONObject(),inputs),"save before initialization refused");JSONObject first=store.initialize(inputs),initial=first.getJSONObject("config");check(first.getString("state").equals("ready"),"explicit initialization");WatchlistWorkspaceStore reopened=new WatchlistWorkspaceStore(context,filename);same(reopened.read(inputs),first,"persistent random IDs/revision reopen");same(reopened.initialize(copy(inputs).put("legacyGroups",new JSONArray())),first,"initialize once no reassignment");
  String groupId=first.getJSONObject("snapshot").getJSONArray("groups").getJSONObject(0).getString("groupId");JSONObject base=first.getJSONObject("snapshot"),draft=apply(base,object("op","renameGroup","groupId",groupId,"name","持久化改名")),packet=prepare(base,draft,base);JSONObject fresh=copy(inputs);fresh.getJSONArray("instruments").getJSONObject(0).put("quote",object("price",33,"color","fall","marker","FRESH_QUOTE_NOT_PERSISTED"));JSONObject saved=store.save(packet,fresh);check(!saved.getString("revision").equals(base.getString("revision")),"new durable revision");same(saved.get("groups"),draft.get("groups"),"exact group save");same(saved.get("instruments"),fresh.get("instruments"),"receipt current quotes no replacement");same(new WatchlistWorkspaceStore(context,filename).read(fresh).get("snapshot"),saved,"lost receipt reread durable exact");rejects(()->reopened.save(packet,fresh),"stale replay rejected");same(store.read(fresh).get("snapshot"),saved,"stale rollback no partial state");same(store.save(prepare(saved,saved,saved),fresh),saved,"no-op no version mutation");String disk=new String(Files.readAllBytes(mainFile.toPath()),StandardCharsets.UTF_8);check(!disk.contains("QUOTE_NEVER_ON_DISK")&&!disk.contains("FRESH_QUOTE_NOT_PERSISTED")&&!disk.contains("\"instruments\""),"disk configuration only no stale/current quote copy");
